/**
 * Post-build bundle scanner (server-side access-control model).
 *
 * After `vite build` produces the deployed bundle in dist/, this step scans
 * every output file for two classes of problem and BLOCKS the release
 * (non-zero exit) on any hit:
 *
 *   1. Supabase account password leakage (Req 11.1, 11.5, 11.6, 11.7). The
 *      candidate password values come from an OPTIONAL, gitignored, local/CI
 *      source that is NEVER a `VITE_` var and is never committed:
 *        - process.env.SCAN_PASSWORDS (comma-separated), and/or
 *        - `.scan-secrets.json` at project root: { "passwords": ["...","..."] }
 *      If no secrets source is configured we print a notice and SKIP the
 *      password portion (lack of a secret list is not, by itself, a failure).
 *
 *   2. Retired client-side encrypted-payload signatures (Req 15.2, 15.5, 15.6).
 *      The old model shipped an AES-encrypted `__payload.js`. If any signature
 *      of that retired path survives into the bundle, the release is blocked.
 *
 * When the bundle is clean it exits zero. Passwords are read from a build-time
 * source only and never ship in the bundle; this scanner is the last gate that
 * guarantees that promise.
 */

import { readFileSync, existsSync, readdirSync, statSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const ROOT = resolve(__dirname, '..');

const SCAN_SECRETS_FILE = resolve(ROOT, '.scan-secrets.json');
const DIST_DIR = resolve(ROOT, 'dist');

/**
 * Pure scan helper. Given some text and a list of candidate secret values,
 * reports whether any secret appears verbatim in the text and exactly which
 * ones. Empty/blank secret values (and non-string inputs) are ignored — they
 * would match everything and are never valid credentials.
 *
 * This behavior is intentionally unchanged from the previous model and is the
 * unit tested / property tested (Property 9) surface of this module.
 *
 * @param {string} text - the text to scan.
 * @param {string[]} secrets - candidate secret values to look for.
 * @returns {{ found: boolean, matches: string[] }}
 */
export function scanText(text, secrets) {
  const haystack = typeof text === 'string' ? text : '';
  const candidates = Array.isArray(secrets) ? secrets : [];
  const matches = [];
  for (const secret of candidates) {
    if (typeof secret !== 'string' || secret.length === 0) continue;
    if (haystack.includes(secret) && !matches.includes(secret)) {
      matches.push(secret);
    }
  }
  return { found: matches.length > 0, matches };
}

/**
 * Signatures of the retired client-side encrypted payload. A small set of
 * robust markers rather than brittle exact-file matching. If any of these
 * appears in a bundle file, the retired encryption path has leaked back in.
 *
 * @param {string} text - the text to scan.
 * @returns {{ found: boolean, signatures: string[] }}
 */
export function scanRetiredPayload(text) {
  const haystack = typeof text === 'string' ? text : '';
  const signatures = [];

  // The generated header stamped onto the old encrypted payload module.
  if (haystack.includes('AUTO-GENERATED by scripts/encrypt-content.mjs')) {
    signatures.push('encrypt-content.mjs auto-generated header');
  }

  // The tiered-payload shape: a `wraps` container alongside the AES cipher id.
  if (haystack.includes('"wraps"') && haystack.includes('AES-256-GCM')) {
    signatures.push('tiered payload shape ("wraps" + AES-256-GCM)');
  }

  // A `payload` export whose object carries the tier/wrap structure.
  if (/\bpayload\b/.test(haystack) && /["']?(tiers|wraps)["']?\s*:/.test(haystack)) {
    signatures.push('payload export containing tiers/wraps');
  }

  return { found: signatures.length > 0, signatures };
}

/**
 * Read candidate Supabase account passwords from the optional, gitignored
 * local/CI source. Returns the list of non-empty password strings, or an empty
 * list when no source is configured. This source is NEVER a `VITE_` var.
 *
 * @returns {string[]}
 */
function readCandidateSecrets() {
  const secrets = [];

  const fromEnv = process.env.SCAN_PASSWORDS;
  if (typeof fromEnv === 'string' && fromEnv.trim().length > 0) {
    for (const part of fromEnv.split(',')) {
      const value = part.trim();
      if (value.length > 0) secrets.push(value);
    }
  }

  if (existsSync(SCAN_SECRETS_FILE)) {
    try {
      const raw = JSON.parse(readFileSync(SCAN_SECRETS_FILE, 'utf8'));
      const list = raw && raw.passwords;
      if (Array.isArray(list)) {
        for (const value of list) {
          if (typeof value === 'string' && value.length > 0) secrets.push(value);
        }
      } else {
        console.warn(
          '⚠️  .scan-secrets.json found but has no `passwords` array; ignoring it.'
        );
      }
    } catch {
      console.warn('⚠️  .scan-secrets.json could not be parsed as JSON; ignoring it.');
    }
  }

  // De-duplicate while preserving order.
  return [...new Set(secrets)];
}

/**
 * Recursively collect every file path under a directory.
 * @param {string} dir
 * @returns {string[]}
 */
function collectFiles(dir) {
  const out = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      out.push(...collectFiles(full));
    } else {
      out.push(full);
    }
  }
  return out;
}

function main() {
  console.log('🔎 Scanning dist/ for secret leakage and retired-payload signatures...');

  if (!existsSync(DIST_DIR)) {
    console.error('\n❌ dist/ not found. Run the build (vite build) before scanning.\n');
    process.exit(1);
  }

  const secrets = readCandidateSecrets();
  if (secrets.length === 0) {
    console.log(
      'ℹ️  No secret source configured (set SCAN_PASSWORDS or add a gitignored ' +
        '.scan-secrets.json). Skipping the password scan; still running the ' +
        'retired-payload signature scan.'
    );
  }

  const files = collectFiles(DIST_DIR);
  const secretLeaks = [];
  const payloadLeaks = [];

  for (const file of files) {
    let text;
    try {
      text = readFileSync(file, 'utf8');
    } catch {
      // Unreadable-as-text (binary) files can't contain a plaintext match
      // against a utf8 read; skip them defensively.
      continue;
    }

    if (secrets.length > 0) {
      const { found } = scanText(text, secrets);
      if (found) secretLeaks.push(file);
    }

    const { found: payloadFound, signatures } = scanRetiredPayload(text);
    if (payloadFound) payloadLeaks.push({ file, signatures });
  }

  const blocked = secretLeaks.length > 0 || payloadLeaks.length > 0;

  if (secretLeaks.length > 0) {
    console.error(
      `\n❌ Password value(s) found in the bundle — release BLOCKED.\n` +
        secretLeaks.map((f) => `   • ${f}`).join('\n') +
        '\n'
    );
  }

  if (payloadLeaks.length > 0) {
    console.error(
      `\n❌ Retired encrypted-payload signature(s) found in the bundle — release BLOCKED.\n` +
        payloadLeaks
          .map((l) => `   • ${l.file}\n       ↳ ${l.signatures.join('; ')}`)
          .join('\n') +
        '\n'
    );
  }

  if (blocked) {
    process.exit(1);
  }

  const scanned = `scanned ${files.length} file(s)`;
  const pwNote =
    secrets.length > 0
      ? `no password values found`
      : `password scan skipped (no secret source)`;
  console.log(`✅ Clean: ${scanned}, ${pwNote}, no retired-payload signatures.`);
  process.exit(0);
}

// Only run the scan when invoked directly (e.g. `node scripts/scan-bundle.mjs`),
// not when imported by a test that just wants the pure helpers.
const isMain = process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url;
if (isMain) {
  main();
}
